const keywordGroups = [
  { name: 'core', weight: 5, keywords: ['n8n', 'ai automation', 'ai agent', 'ai agents', 'agentic ai', 'agentic automation', 'workflow automation', 'business process automation', 'ai integration', 'agent orchestration'] },
  { name: 'agents_mcp', weight: 4, keywords: ['model context protocol', 'mcp', 'mcp server', 'mcp client', 'mcp tools', 'multi-agent', 'autonomous agent', 'agent framework', 'agent tools', 'tool calling', 'function calling', 'computer use', 'browser agent', 'agent memory', 'agent skills'] },
  { name: 'ai_development', weight: 3, keywords: ['vibe coding', 'ai coding', 'agentic coding', 'coding agent', 'ai ide', 'ai app builder', 'codex', 'claude code', 'cursor', 'windsurf', 'replit agent', 'github copilot', 'gemini cli', 'openai', 'anthropic', 'claude', 'gemini'] },
  { name: 'frameworks_tools', weight: 3, keywords: ['langchain', 'langgraph', 'crewai', 'llamaindex', 'openai agents sdk', 'google adk', 'make.com', 'zapier', 'activepieces'] },
  { name: 'llm_infrastructure', weight: 2, keywords: ['llm integration', 'llm automation', 'rag', 'vector database', 'embeddings', 'structured output', 'context engineering', 'semantic search', 'knowledge base'] },
  { name: 'business_automation', weight: 2, keywords: ['crm automation', 'sales automation', 'lead automation', 'lead qualification', 'marketing automation', 'customer support automation', 'document automation', 'document processing', 'content automation', 'email automation', 'reporting automation', 'e-commerce automation'] },
  { name: 'technology_event', weight: 1, keywords: ['released', 'launch', 'launched', 'introducing', 'new feature', 'new integration', 'new api', 'new model', 'update', 'changelog', 'beta', 'general availability', 'open source', 'sdk', 'connector', 'integration'] },
];
const MIN_SCORE = 5;
const escapeRegExp = value => value.replace(/[-/\\^$*+?.()|[\]{}]/g, '\\$&');
const hasKeyword = (text, keyword) => new RegExp('(^|[^a-z0-9])' + escapeRegExp(keyword) + '($|[^a-z0-9])', 'i').test(text);
return items.map((item, index) => {
  const data = item.json;
  const text = [data['title (Заголовок)'], data['description (Опис)'], data['search_text (Текст для пошуку)'], data['categories (Категорії)'], data['source_name (Назва джерела)']].filter(Boolean).join(' ').toLowerCase();
  let score = 0;
  const matchedKeywords = [];
  const matchedGroups = [];
  for (const group of keywordGroups) {
    let groupMatched = false;
    for (const keyword of group.keywords) {
      if (hasKeyword(text, keyword)) {
        score += group.weight;
        matchedKeywords.push(keyword);
        groupMatched = true;
      }
    }
    if (groupMatched) matchedGroups.push(group.name);
  }
  return { json: { ...data, keyword_score: score, matched_keywords: [...new Set(matchedKeywords)], matched_groups: [...new Set(matchedGroups)], keyword_relevant: score >= MIN_SCORE }, pairedItem: item.pairedItem ?? { item: index } };
});

const countItems = (nodeName) => {
  try {
    return $(nodeName).all().length;
  } catch {
    return 0;
  }
};

const sumField = (nodeName, fieldName) => {
  try {
    return $(nodeName).all().reduce(
      (sum, item) => sum + Number(item.json[fieldName] ?? 0),
      0,
    );
  } catch {
    return 0;
  }
};

const run = $('Prepare Analyst Run Start').first().json;
const keywordFiltered = countItems('Mark News Keyword Filtered');
const irrelevant = countItems('Mark News Irrelevant');
const analyzed = countItems('Mark News Analyzed');
const classified = countItems('Normalize HTTP Relevance');
const signalsWritten = countItems('Write Tech Signal');

const inputTokens =
  sumField('Normalize HTTP Relevance', 'relevance_input_tokens') +
  sumField('Normalize HTTP Tech Signal', 'analysis_input_tokens');
const cachedInputTokens =
  sumField('Normalize HTTP Relevance', 'relevance_cached_input_tokens') +
  sumField('Normalize HTTP Tech Signal', 'analysis_cached_input_tokens');
const outputTokens =
  sumField('Normalize HTTP Relevance', 'relevance_output_tokens') +
  sumField('Normalize HTTP Tech Signal', 'analysis_output_tokens');
const totalTokens =
  sumField('Normalize HTTP Relevance', 'relevance_total_tokens') +
  sumField('Normalize HTTP Tech Signal', 'analysis_total_tokens');

const INPUT_RATE_PER_MILLION = 0.75;
const CACHED_INPUT_RATE_PER_MILLION = 0.075;
const OUTPUT_RATE_PER_MILLION = 4.50;
const billableInputTokens = Math.max(0, inputTokens - cachedInputTokens);
const estimatedCostUsd = Number((
  (billableInputTokens / 1_000_000) * INPUT_RATE_PER_MILLION +
  (cachedInputTokens / 1_000_000) * CACHED_INPUT_RATE_PER_MILLION +
  (outputTokens / 1_000_000) * OUTPUT_RATE_PER_MILLION
).toFixed(8));

const finishedAt = $now.toISO();
const durationSeconds = Math.max(
  0,
  Math.round($now.diff(DateTime.fromISO(run.started_at), 'seconds').seconds),
);

return [{
  json: {
    run_id: run.run_id,
    n8n_execution_id: run.n8n_execution_id,
    workflow_name: run.workflow_name,
    workflow_category: run.workflow_category,
    trigger_type: run.trigger_type,
    started_at: run.started_at,
    finished_at: finishedAt,
    duration_seconds: durationSeconds,
    run_status: 'success',
    items_input: run.items_input,
    items_processed: keywordFiltered + irrelevant + analyzed,
    items_created: 0,
    items_updated: 0,
    items_skipped: keywordFiltered + irrelevant,
    items_failed: 0,
    ai_calls: classified + signalsWritten,
    model_name: run.model_name,
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    total_tokens: totalTokens,
    estimated_cost_usd: estimatedCostUsd,
    run_metadata: JSON.stringify({
      filter_threshold: 5,
      batch_limit: 10,
      tech_signals_written: signalsWritten,
      relevance_calls: classified,
      signal_analysis_calls: signalsWritten,
      cached_input_tokens: cachedInputTokens,
      pricing_usd_per_million: {
        input: INPUT_RATE_PER_MILLION,
        cached_input: CACHED_INPUT_RATE_PER_MILLION,
        output: OUTPUT_RATE_PER_MILLION,
      },
      finalization_scope: 'normal_terminal_paths',
    }),
  },
}];

const ID = 'tech_signal_id (ID технологічного сигналу)';
const SOURCES = 'source_news_ids (ID вихідних новин)';

const splitIds = (value) =>
  String(value ?? '')
    .split(',')
    .map(id => id.trim())
    .filter(Boolean);

// Lookup can return one blank item when no signals exist yet.
// Build an explicit map by ID instead of relying on n8n's ambiguous .item pairing.
const existingSourcesById = new Map();
for (const item of $input.all()) {
  const record = item.json;
  if (!record[ID]) continue;

  const ids = existingSourcesById.get(record[ID]) ?? [];
  existingSourcesById.set(record[ID], [...ids, ...splitIds(record[SOURCES])]);
}

return $('Prepare Tech Signal Row').all().map((item, index) => {
  const current = item.json;
  const mergedIds = [
    ...new Set([
      ...splitIds(current[SOURCES]),
      ...(existingSourcesById.get(current[ID]) ?? []),
    ]),
  ];

  return {
    json: {
      ...current,
      [SOURCES]: mergedIds.join(','),
    },
    pairedItem: { item: index },
  };
});

