={{ ({
      model: "gpt-5.4-mini",
      store: false,
      max_output_tokens: 220,
      instructions: "You are an AI Technology Analyst. Assess only the supplied news material. Return is_relevant=true only for concrete technology changes or practical capabilities related to n8n, AI automation, AI agents, integrations, Model Context Protocol (MCP), vibe coding, AI coding tools, or adjacent enabling technologies. General company news, broad opinions, unrelated research, education stories, and incidents without a new capability are irrelevant. Do not invent facts. Write reason in Ukrainian.",
      input: "Title: " + ($json["title (Заголовок)"] ?? "") + "\n\nDescription: " + ($json["description (Опис)"] ?? "") + "\n\nCategories: " + ($json["categories (Категорії)"] ?? "") + "\nSource: " + ($json["source_name (Назва джерела)"] ?? "") + "\n\nKeyword pre-filter score: " + ($json.keyword_score ?? "") + "\nMatched groups: " + (($json.matched_groups ?? []).join(", ")) + "\nMatched keywords: " + (($json.matched_keywords ?? []).join(", ")),
      text: {
        format: {
          type: "json_schema",
          name: "news_relevance",
          strict: true,
          schema: {
            type: "object",
            additionalProperties: false,
            properties: {
              is_relevant: { type: "boolean", description: "True only for relevant technology news." },
              reason: { type: "string", description: "Concise evidence-based explanation in Ukrainian." },
              confidence: { type: "number", minimum: 0, maximum: 1, description: "Confidence based only on supplied news fields." }
            },
            required: ["is_relevant","reason","confidence"]
          }
        }
      }
    }) }}

